// Asking DeArrow about videos and deciding what their tiles show: a queue of
// lookups (four at a time, in screen order), the branding answer per video,
// then the title and the thumbnail, with each improvement handed to the
// sweep. A random frame can take the thumbnail server tens of seconds to
// render, so YouTube's auto-generated start frame stands in until it does, as
// in the extension.
//
// Like SponsorBlock, a branding request names only the first four characters
// of the SHA-256 of a video id, and the answer holds every video under that
// prefix that has a submission: one request serves every video of the page
// under the same prefix. A video id is sent only where a frame of it is asked
// for, which names it anyway: the thumbnail server, and the random frame's
// time for a video nobody submitted anything for.
import sha256 from 'tiny-sha256';
import { configRead } from '../config.js';
import { fetchJsonWithTimeout } from '../fetch-timeout.js';
import {
  AUTOGENERATED_FRAMES,
  BLANK_THUMB,
  BRANDING_API,
  FETCH_TIMEOUT_MS,
  MAX_CONCURRENT,
  RANDOM_FRAME_RETRIES_MS,
  THUMBNAIL_API
} from './constants.js';
import { videos, currentGeneration } from './state.js';
import { loadThumb } from './thumbs.js';
import { isTrusted, resolveTitle, crowdsourcedTitle } from './titles.js';

const DEBUG = false;
// A lookup that failed (offline, the server down) is asked again when a
// response shows the video after this long.
const RETRY_AFTER_MS = 60000;

const queue = [];
let active = 0;
// Hash prefix -> the branding request in flight for it.
const prefixRequests = new Map();
// Called with the video when what its tiles should show changed (index.js).
let onChange = () => {};

/** Sets what runs (with the video) when a video's title or thumbnail changed. */
export function setChangeHandler(fn) {
  onChange = fn;
}

/** The first four characters of the SHA-256 of a video id: all a branding request names. */
export const prefixOf = (videoId) => sha256(videoId).substring(0, 4);

/** The thumbnail server's URL for the frame of `videoId` at `time` seconds. */
const thumbnailUrl = (videoId, time) => `${THUMBNAIL_API}?videoID=${videoId}&time=${time}`;

/**
 * Whether a video should be looked up again now: never answered, not waiting
 * or being looked up, and its last failure (if any) RETRY_AFTER_MS ago.
 */
export const wantsLookup = (video) =>
  !video.fetched && !video.queued && !video.looking && Date.now() >= video.retryAt;

/**
 * The branding of every video with a submission under `prefix`: an object by
 * video id ({} for a 404, nothing under it), or null when the request failed.
 * Asked once while in flight, however many videos wait for it.
 */
function brandingByPrefix(prefix) {
  let request = prefixRequests.get(prefix);
  if (!request) {
    request = fetchJsonWithTimeout(`${BRANDING_API}/${prefix}`, FETCH_TIMEOUT_MS).then(
      (res) => {
        if (res.ok) return res.data && typeof res.data === 'object' ? res.data : {};
        return res.status === 404 ? {} : null;
      },
      (e) => {
        if (DEBUG) console.info('[DeArrow] Branding lookup failed for', prefix, e.message);
        return null;
      }
    );
    prefixRequests.set(prefix, request);
    request.then(() => prefixRequests.delete(prefix));
  }
  return request;
}

/**
 * Hands an answer to every video under its prefix still waiting for one, so
 * the videos queued behind need no request of their own. Only those: an
 * answer names about 170 videos, most of them never shown.
 */
function settlePrefix(prefix, answer) {
  videos.forEach((video, videoId) => {
    if (video.fetched || video.prefix !== prefix) return;
    const raw = answer[videoId];
    video.raw = raw && typeof raw === 'object' ? raw : null;
    video.fetched = true;
  });
}

/**
 * The random frame's time in seconds, from the server's random position and
 * the video's length, so the frame is the one other DeArrow users already had
 * rendered; null without them (offline), and the auto-generated frame stays.
 * A video nobody submitted anything for is not in the prefix answer: its
 * random time is asked for by its id, which the frame request names anyway
 * (a 404 there still carries it).
 */
async function randomFrameTime(videoId, video) {
  let info = video.raw && video.raw.randomTime != null ? video.raw : null;
  if (!info) {
    if (!video.randomInfo) {
      video.randomInfo = fetchJsonWithTimeout(
        `${BRANDING_API}?videoID=${videoId}`,
        FETCH_TIMEOUT_MS,
        { bodyOn: [404] }
      ).then(
        (res) => (res.data && typeof res.data === 'object' ? res.data : null),
        () => null
      );
    }
    info = await video.randomInfo;
  }
  const duration = (info && info.videoDuration) || video.duration;
  const randomTime = info ? info.randomTime : null;
  return duration && typeof randomTime === 'number' ? randomTime * duration : null;
}

/**
 * Decides the thumbnail, calling show(thumb, crowdsourced) with each improvement: a trusted
 * crowdsourced frame, or the fallback the settings pick (YouTube's own, a
 * blank, one of YouTube's auto-generated frames, or a random frame with the
 * start frame standing in until the server has rendered it).
 */
async function resolveThumb(videoId, video, gen, show) {
  if (!configRead('dearrowCrowdThumbnails')) {
    show(null);
    return;
  }

  const custom = video.raw && Array.isArray(video.raw.thumbnails) ? video.raw.thumbnails[0] : null;
  if (isTrusted(custom) && typeof custom.timestamp === 'number') {
    // officialTime: the time is a submitted one, so the server makes the
    // frame now when it has none cached, instead of answering empty.
    const url = thumbnailUrl(videoId, custom.timestamp) + '&officialTime=true&generateNow=true';
    show(await loadThumb(url, videoId), true);
    return;
  }
  // The community voted for YouTube's own thumbnail.
  if (custom && custom.original && (custom.locked || custom.votes >= 0)) {
    show(null);
    return;
  }

  const fallback = configRead('dearrowThumbnailFallback');
  if (fallback === 'original') {
    show(null);
    return;
  }
  if (fallback === 'blank') {
    show(BLANK_THUMB + videoId);
    return;
  }

  // Start, middle or end; the start frame for the random frame's stand-in.
  const frame = AUTOGENERATED_FRAMES[fallback] || AUTOGENERATED_FRAMES.start;
  const autogenerated = `https://i.ytimg.com/vi/${videoId}/${frame}.jpg`;
  const time = fallback === 'random' ? await randomFrameTime(videoId, video) : null;
  if (gen !== currentGeneration()) return;
  if (time === null) {
    show(await loadThumb(autogenerated, videoId));
    return;
  }

  const url = thumbnailUrl(videoId, time);
  const ready = await loadThumb(url + '&generateNow=true', videoId);
  if (ready) {
    show(ready);
    return;
  }
  show(await loadThumb(autogenerated, videoId));
  // Not awaited: the lookup moves on to the next video meanwhile.
  /** Asks for the random frame again after the next delay, until it comes or the delays run out. */
  const retry = (delays) => {
    if (!delays.length) return;
    setTimeout(async () => {
      if (gen !== currentGeneration()) return;
      const later = await loadThumb(url, videoId);
      if (later) show(later);
      else retry(delays.slice(1));
    }, delays[0]);
  };
  retry(RANDOM_FRAME_RETRIES_MS);
}

/** Decides `video`'s title, then its thumbnail; output from an older generation is dropped. */
async function resolve(videoId, video) {
  if (!configRead('enableDeArrow')) return;
  const gen = currentGeneration();
  const title = await resolveTitle(video);
  if (gen !== currentGeneration()) return;
  video.title = title;
  // What the community submitted, as opposed to a random frame or formatting:
  // what the DeArrow badge marks (tiles.js).
  video.crowdTitle = !!title && !!crowdsourcedTitle(video);
  video.resolved = true;
  onChange(video);

  await resolveThumb(videoId, video, gen, (thumb, crowdsourced) => {
    if (gen !== currentGeneration()) return;
    const changed = video.thumb !== thumb;
    video.thumb = thumb;
    video.crowdThumb = !!thumb && !!crowdsourced;
    if (changed) onChange(video);
  });
}

/** Asks about one video (once its prefix answered), then decides what its tiles show. */
async function lookup(videoId) {
  const video = videos.get(videoId);
  if (!video) return;
  video.queued = false;
  video.looking = true;
  try {
    if (!video.fetched) {
      if (!video.prefix) video.prefix = prefixOf(videoId);
      const answer = await brandingByPrefix(video.prefix);
      // Wiped meanwhile (too many videos, or DeArrow off): nothing to write to.
      if (videos.get(videoId) !== video) return;
      if (answer) settlePrefix(video.prefix, answer);
      else video.retryAt = Date.now() + RETRY_AFTER_MS;
    }
    // Formatting the original title can still apply without an answer.
    await resolve(videoId, video);
  } finally {
    video.looking = false;
  }
}

/** Starts queued lookups until MAX_CONCURRENT run. */
function pump() {
  while (active < MAX_CONCURRENT && queue.length && configRead('enableDeArrow')) {
    const videoId = queue.shift();
    active++;
    /** One lookup done: start the next. */
    const next = () => {
      active--;
      pump();
    };
    lookup(videoId).then(next, next);
  }
}

/** Queues `ids` for a lookup, in order, and starts what can start. */
export function queueLookups(ids) {
  for (let i = 0; i < ids.length; i++) {
    const video = videos.get(ids[i]);
    if (!video || video.queued) continue;
    // Hashed now, in screen order, so an answer can settle the videos queued behind.
    if (!video.prefix) video.prefix = prefixOf(ids[i]);
    video.queued = true;
    queue.push(ids[i]);
  }
  pump();
}

/** Empties the queue (lookups already running finish, their output dropped by generation). */
export function clearQueue() {
  for (let i = 0; i < queue.length; i++) {
    const video = videos.get(queue[i]);
    if (video) video.queued = false;
  }
  queue.length = 0;
}
